package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserBase;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.sym.CharsToNameCanonicalizer;
import com.fasterxml.jackson.core.util.*;
import com.fasterxml.jackson.core.util.BufferRecycler;
import java.io.*;
import java.io.IOException;
import java.io.StringReader;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for ReaderBasedJsonParser._finishString2
 */
public class ReaderBasedJsonParser__finishString2_TriageGen1Test {

    private ReaderBasedJsonParser parser;
    private String inputJson;

    @Before
    public void setUp() throws Exception {
        // We use a StringReader to simulate input
    }

    /**
     * Helper to instantiate the protected parser via reflection or a public wrapper.
     * Since the constructor is public, we can use it.
     */
    private ReaderBasedJsonParser createParser(String input) throws Exception {
        StringReader reader = new StringReader(input);
        // Constructor: public ReaderBasedJsonParser(IOContext ctxt, int features, Reader r, ObjectCodec codec, CharsToNameCanonicalizer st);
        // Passing nulls for codec and canonicalizer as they aren't strictly required for this specific method logic
        return new ReaderBasedJsonParser(IOContext.bootstrap(), 0, reader, null, null);
    }

    /**
     * Helper to invoke the protected _finishString2 method via reflection.
     */
    private void invokeFinishString2(ReaderBasedJsonParser parser) throws Exception {
        Method method = ReaderBasedJsonParser.class.getDeclaredMethod("_finishString2");
        method.setAccessible(true);
        method.invoke(parser);
    }

    /**
     * Helper to manually set the internal state of the parser to simulate being inside a string.
     * This is necessary because _finishString2 assumes the parser is already at the start of the content 
     * inside the quotes.
     */
    private void prepareParserForString(ReaderBasedJsonParser parser, String contentInsideQuotes) throws Exception {
        // We need to simulate the state where the parser has already consumed the opening quote
        // and is positioned at the first character of the string content.

        // 1. Set the input buffer
        Field inputBufferField = ReaderBasedJsonParser.class.getDeclaredField("_inputBuffer");
        inputBufferField.setAccessible(true);
        char[] buffer = (contentInsideQuotes + "\"").toCharArray();
        inputBufferField.set(parser, buffer);

        // 2. Set pointers
        Field inputPtrField = ReaderBasedJsonParser.class.getDeclaredField("_inputPtr");
        inputPtrField.setAccessible(true);
        inputPtrField.set(parser, 0);

        Field inputEndField = ReaderBasedJsonParser.class.getDeclaredField("_inputEnd");
        inputEndField.setAccessible(true);
        inputEndField.set(parser, buffer.length);

        // 3. Ensure the text buffer is ready to receive characters
        // The _textBuffer is usually a TextBuffer object inside the parser
        Field textBufferField = ReaderBasedJsonParser.class.getDeclaredField("_textBuffer");
        textBufferField.setAccessible(true);
        Object textBuffer = textBufferField.get(parser);

        // We call the parser's internal methods to ensure the segment is initialized if needed
        // but usually, the constructor or previous parsing steps do this.
    }

    @Test
    public void testFinishString_Simple() throws Exception {
        String content = "hello";
        parser = createParser("\"" + content + "\"");
        // Move parser to the state where it's ready to finish the string
        // In a real scenario, nextToken() would be called. 
        // Here we simulate the internal state.
        prepareParserForString(parser, content);

        invokeFinishString2(parser);

        assertEquals(content, parser.getText());
    }

    @Test
    public void testFinishString_WithEscapedChar() throws Exception {
        String content = "a\\nb"; // \n is two chars in string, but represents one escaped char
        // However, the method calls _decodeEscaped(). 
        // To test _decodeEscaped, we need to provide a valid escape sequence.
        String escapedContent = "a\"b"; // This is tricky because " is a quote.
        // Let's use a simple backslash escape: \"
        prepareParserForString(parser = createParser(""), "a\\\"b");

        invokeFinishString2(parser);

        assertEquals("a\"b", parser.getText());
    }

    @Test
    public void testFinishString_BufferOverflow() throws Exception {
        // To trigger 'outPtr >= outBuf.length', we need a small buffer.
        // Since we can't easily control the internal TextBuffer size via the public API,
        // we rely on the fact that TextBuffer will eventually hit its limit and call finishCurrentSegment.

        StringBuilder longContent = new StringBuilder();
        for (int i = 0; i < 1000; i++) {
            longContent.append("a");
        }
        String content = longContent.toString();

        parser = createParser("\"" + content + "\"");
        prepareParserForString(parser, content);

        invokeFinishString2(parser);

        assertEquals(content, parser.getText());
    }

    @Test(expected = Exception.class) // Expecting JsonParseException or IOException
    public void testFinishString_UnclosedQuote() throws Exception {
        // This tests the 'if (!loadMore())' and '_reportInvalidEOF' path
        // We provide a string that ends without a quote and no more data.
        parser = createParser("\"unclosed");
        prepareParserForString(parser, "unclosed");

        // Force inputEnd to be small so loadMore() is called and fails
        Field inputEndField = ReaderBasedJsonParser.class.getDeclaredField("_inputEnd");
        inputEndField.setAccessible(true);
        inputEndField.set(parser, 8); 

        invokeFinishString2(parser);
    }

    @Test(expected = Exception.class)
    public void testFinishString_InvalidUnquotedSpace() throws Exception {
        // Tests '_throwUnquotedSpace'
        // This happens if a control character (i < INT_SPACE) is found that isn't a backslash or quote
        // Character 1 (SOH) is < INT_SPACE
        prepareParserForString(parser = createParser(""), String.valueOf((char) 1));

        invokeFinishString2(parser);
    }

    @Test
    public void testFinishString_EmptyString() throws Exception {
        prepareParserForString(parser = createParser("\"\""), "");
        invokeFinishString2(parser);
        assertEquals("", parser.getText());
    }

    @Test
    public void testFinishString_BackslashAtEnd() throws Exception {
        // Tests the loop and escape logic for a single backslash followed by quote
        // This is technically an invalid escape in JSON, but we test the code path
        prepareParserForString(parser = createParser(""), "\\\"");
        // Note: _decodeEscaped() will be called. 
        // If the input is just \ and then ", _decodeEscaped will likely throw an error.
        try {
            invokeFinishString2(parser);
        } catch (Exception e) {
            // Expected behavior for invalid escape
        }
    }
}
